task set_word; input integer address; input [15:0] data; integer p;
begin for(p=0;p<8;p=p+1) rom[address*8+p]=data[p*2+:2]; end endtask
always @(posedge I_clk) O_cov<=rom[I_addr];
endmodule
// LOSSLESS_PACKED_FONT_20261002
// Identical native 24px coverage: 64372 pixels in fourteen 512x18 ROMs.
// The empty space glyph is bypassed; all 132 other glyphs use stride 54.
// Row quotient/remainder descriptors avoid pixel-path division.
module lyric_font_packed9_reference(input I_clk,input [7:0] I_glyph,
    input [4:0] I_row,I_col,output [1:0] O_cov);
wire [7:0] slot=I_glyph-8'd1;
wire [12:0] base_word=({5'd0,slot}<<6)-({5'd0,slot}<<3)-({5'd0,slot}<<1);
reg [5:0] row_word; reg [3:0] row_lane;
always @(*) begin row_word=0; row_lane=0; case(I_row)
    5'd0: begin row_word=6'd0; row_lane=4'd0; end
    5'd1: begin row_word=6'd2; row_lane=4'd4; end
    5'd2: begin row_word=6'd4; row_lane=4'd8; end
    5'd3: begin row_word=6'd7; row_lane=4'd3; end
    5'd4: begin row_word=6'd9; row_lane=4'd7; end
    5'd5: begin row_word=6'd12; row_lane=4'd2; end
    5'd6: begin row_word=6'd14; row_lane=4'd6; end
    5'd7: begin row_word=6'd17; row_lane=4'd1; end
    5'd8: begin row_word=6'd19; row_lane=4'd5; end
    5'd9: begin row_word=6'd22; row_lane=4'd0; end
    5'd10: begin row_word=6'd24; row_lane=4'd4; end
    5'd11: begin row_word=6'd26; row_lane=4'd8; end
    5'd12: begin row_word=6'd29; row_lane=4'd3; end
    5'd13: begin row_word=6'd31; row_lane=4'd7; end
    5'd14: begin row_word=6'd34; row_lane=4'd2; end
    5'd15: begin row_word=6'd36; row_lane=4'd6; end
    5'd16: begin row_word=6'd39; row_lane=4'd1; end
    5'd17: begin row_word=6'd41; row_lane=4'd5; end
    5'd18: begin row_word=6'd44; row_lane=4'd0; end
    5'd19: begin row_word=6'd46; row_lane=4'd4; end
    5'd20: begin row_word=6'd48; row_lane=4'd8; end
    5'd21: begin row_word=6'd51; row_lane=4'd3; end
endcase end
wire [1:0] col_word=I_col>=18?2'd2:I_col>=9?2'd1:2'd0;
wire [3:0] col_lane=I_col>=18?I_col-5'd18:I_col>=9?I_col-5'd9:I_col;
wire [4:0] lane_sum={1'b0,row_lane}+{1'b0,col_lane};
wire carry_word=lane_sum>=5'd9;
wire [3:0] lane=carry_word?lane_sum-5'd9:lane_sum;
wire [5:0] word_offset=row_word+{4'd0,col_word}+{5'd0,carry_word};
wire [12:0] address=base_word+{7'd0,word_offset};
wire [447:0] bank_data; reg [3:0] bank_select,lane_select; reg blank; genvar b;
generate for(b=0;b<14;b=b+1) begin: banks
    lyric_packed_font_bank #(.BANK_ID(b)) bank(I_clk,address[8:0],bank_data[b*32+:18]);
    assign bank_data[b*32+18+:14]=14'd0;
end endgenerate
always @(posedge I_clk) begin bank_select<=address[12:9]; lane_select<=lane; blank<=(I_glyph==0); end
wire [17:0] selected=bank_data[{bank_select,5'd0}+:18];
assign O_cov=blank?2'd0:selected[{lane_select,1'b0}+:2];
endmodule

